# owner: platform
"""Seating charts: students sorted by last name, in rows."""

from typing import List

from rosterkit.models import Student


def _name(student: Student) -> str:
    return f"{student.last_name}, {student.first_name}"


def _line(number: int, row: List[Student]) -> str:
    return f"Row {number}: " + " | ".join(map(_name, row))


def _chunks(items: list, size: int) -> List[list]:
    starts = range(0, len(items), size)
    return [items[i:i + size] for i in starts]


# ---
def seating_rows(students, seats):
    """One text line per row, sorted by last name."""
    if seats <= 0 or not students:
        raise ValueError("need students and seats")
    rows = _chunks(sorted(students, key=_name), seats)
    return [_line(n, r) for n, r in enumerate(rows, 1)]

