# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def _s(last, first):
    return Student("1", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        people = [_s("Halloway", "Juno")]
        people.append(_s("Dunmere", "Piet"))
        people.append(_s("Aske", "Ola"))
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Aske, Ola | Dunmere, Piet",
                "Row 2: Halloway, Juno",
            ],
        )

    def test_bad_seats(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows([_s("A", "B")], seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
